const booking = $('Parse Booking Details').first().json;
// Check for empty calendar events
let events = $('Get Calendar Events').all().map(item => item.json);
if (!events || events.length === 0) {
  events = []; // Continue with empty events
}

const WORK_START_HOUR = 10;
const WORK_END_HOUR = 21;

const SEARCH_WINDOW_MINUTES = 180;
const STEP_MINUTES = 15;

const durationMinutes = booking.duration_minutes || 60;
const bufferMinutes = booking.buffer_minutes || 15;
const totalMinutes = durationMinutes + bufferMinutes;

function pad(n) {
  return String(n).padStart(2, '0');
}

function timeToMinutes(time) {
  const [h, m] = String(time).split(':').map(Number);
  return h * 60 + m;
}

function minutesToTime(total) {
  const h = Math.floor(total / 60);
  const m = total % 60;
  return `${pad(h)}:${pad(m)}`;
}

function eventTimeToMinutes(value, refDate) {
  if (!value) return null;

  try {
    const match = String(value).match(/T(\d{2}):(\d{2})/);
    if (match) {
      return Number(match[1]) * 60 + Number(match[2]);
    }
    if (!value.includes('T')) {
      return null;
    }
    return null;
  } catch (e) {
    return null;
  }
}

function isSameDay(isoDateTime1, isoDateTime2) {
  const date1 = String(isoDateTime1).split('T')[0];
  const date2 = String(isoDateTime2).split('T')[0];
  return date1 === date2;
}

function overlaps(startA, endA, startB, endB) {
  return startA < endB && endA > startB;
}

function isFree(slotStart, slotEnd) {
  for (const event of events) {
    if (!event.start || !event.end) continue;

    const eventStartRaw = event.start.dateTime || event.start.date;
    const eventEndRaw = event.end.dateTime || event.end.date;

    const eventStart = eventTimeToMinutes(eventStartRaw);
    const eventEnd = eventTimeToMinutes(eventEndRaw);

    if (eventStart === null || eventEnd === null) continue;

    const blockedStart = eventStart;

    // исправлено: убран двойной буфер
    const blockedEnd = eventEnd;

    if (overlaps(slotStart, slotEnd, blockedStart, blockedEnd)) {
      return false;
    }
  }

  return true;
}

const requestedStartMinutes = timeToMinutes(booking.time);

const workStartMinutes = WORK_START_HOUR * 60;
const workEndMinutes = WORK_END_HOUR * 60;

const searchStart = Math.max(
  workStartMinutes,
  requestedStartMinutes - SEARCH_WINDOW_MINUTES
);

const searchEnd = Math.min(
  workEndMinutes,
  requestedStartMinutes + SEARCH_WINDOW_MINUTES
);

const after = [];
const before = [];

for (
  let slotStart = requestedStartMinutes + STEP_MINUTES;
  slotStart <= searchEnd;
  slotStart += STEP_MINUTES
) {
  const slotEnd = slotStart + totalMinutes;

  if (slotEnd > workEndMinutes) continue;

  if (isFree(slotStart, slotEnd)) {
    after.push(slotStart);
  }

  if (after.length >= 2) break;
}

for (
  let slotStart = requestedStartMinutes - STEP_MINUTES;
  slotStart >= searchStart;
  slotStart -= STEP_MINUTES
) {
  const slotEnd = slotStart + totalMinutes;

  if (slotStart < workStartMinutes) continue;

  if (isFree(slotStart, slotEnd)) {
    before.push(slotStart);
  }

  if (before.length >= 1) break;
}

const nearby = [...before.reverse(), ...after]
  .slice(0, 3)
  .map(slot => minutesToTime(slot));

const requestedTime = String(booking.time).slice(0, 5);

let message;

if (nearby.length > 0) {
  message =
`Sorry — ${booking.pretty_date} at ${requestedTime} is already booked.

Closest available times:

• ${nearby.join('\n• ')}

Or send another preferred time 💅`;
} else {
  message =
`Sorry — ${booking.pretty_date} at ${requestedTime} is already booked.

I couldn't find free nearby times on this day.

Please send another preferred time 💅`;
}

return [
  {
    json: {
      ...booking,
      nearby_free_times: nearby,
      message
    }
  }
];

