const telegram = $('Telegram Trigger').first().json;
const r = $('Check New Slot Conflict').first().json;
const events = $('Get New Slot Events').all().map(item => item.json).filter(e => e && (e.id || e.start || e.summary));

const WORK_START_HOUR = 10;
const WORK_END_HOUR = 21;
const SEARCH_WINDOW_MINUTES = 180;
const STEP_MINUTES = 15;

function pad(n) {
  return String(n).padStart(2, '0');
}

function minutesToTime(total) {
  const h = Math.floor(total / 60);
  const m = total % 60;
  return `${pad(h)}:${pad(m)}`;
}

function minutesFromTimeValue(value) {
  const match = String(value || '').match(/T?(\d{2}):(\d{2})/);
  if (!match) return null;
  return Number(match[1]) * 60 + Number(match[2]);
}

function sameDate(raw, dateISO) {
  return String(raw || '').split('T')[0] === String(dateISO || '');
}

function overlaps(startA, endA, startB, endB) {
  return startA < endB && endA > startB;
}

const requestedStart = minutesFromTimeValue(r.new_time || r.new_start_datetime);
const requestedDate = String(r.new_date || r.new_start_datetime || '').split('T')[0];
const durationMinutes = r.original_duration_minutes || r.total_minutes || 75;
const workStart = WORK_START_HOUR * 60;
const workEnd = WORK_END_HOUR * 60;

function isFree(slotStart, slotEnd) {
  for (const event of events) {
    if (event.id && event.id === r.event_id) continue;

    const sRaw = event.start?.dateTime || event.start?.date;
    const eRaw = event.end?.dateTime || event.end?.date;
    if (!sRaw || !eRaw) continue;

    if (!String(sRaw).includes('T') || !String(eRaw).includes('T')) {
      if (sameDate(sRaw, requestedDate)) return false;
      continue;
    }

    if (!sameDate(sRaw, requestedDate)) continue;

    const eventStart = minutesFromTimeValue(sRaw);
    const eventEnd = minutesFromTimeValue(eRaw);
    if (eventStart === null || eventEnd === null) continue;

    if (overlaps(slotStart, slotEnd, eventStart, eventEnd)) return false;
  }
  return true;
}

function nearbyFreeTimes() {
  if (requestedStart === null) return [];
  const searchStart = Math.max(workStart, requestedStart - SEARCH_WINDOW_MINUTES);
  const searchEnd = Math.min(workEnd, requestedStart + SEARCH_WINDOW_MINUTES);
  const before = [];
  const after = [];

  for (let slotStart = requestedStart + STEP_MINUTES; slotStart <= searchEnd; slotStart += STEP_MINUTES) {
    const slotEnd = slotStart + durationMinutes;
    if (slotEnd > workEnd) continue;
    if (isFree(slotStart, slotEnd)) after.push(slotStart);
    if (after.length >= 2) break;
  }

  for (let slotStart = requestedStart - STEP_MINUTES; slotStart >= searchStart; slotStart -= STEP_MINUTES) {
    const slotEnd = slotStart + durationMinutes;
    if (slotStart < workStart || slotEnd > workEnd) continue;
    if (isFree(slotStart, slotEnd)) before.push(slotStart);
    if (before.length >= 1) break;
  }

  return [...before.reverse(), ...after].slice(0, 3).map(minutesToTime);
